SELECT * FROM (SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 200 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(AVG(quantity), 2) AS avg_quantity, SUM(quantity * unit_price) AS revenue FROM order_items WHERE product_id = 11 GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 200 THEN 'mid' ELSE 'low' END) AS sub WHERE avg_quantity < 70 ORDER BY avg_quantity DESC
